SELECT k.i, r.root FROM unnest($1::bytea[], $2::bigint[]) WITH ORDINALITY AS k(digest, length, i) LEFT JOIN LATERAL (SELECT f.root FROM {s}.file_digest f WHERE f.digest = k.digest AND f.length = k.length AND EXISTS (SELECT 1 FROM {s}.object_location o WHERE ('x' || encode(substring(o.object_id FROM 1 FOR 8), 'hex'))::bit(64)::bigint = ('x' || encode(substring(f.root FROM 1 FOR 8), 'hex'))::bit(64)::bigint AND o.object_id = f.root OFFSET 0)) r ON true ORDER BY k.i;
